// @ts-nocheck
export interface Country {
  code: string
  name: string
  flag: string
  currency: string
  currencySymbol: string
  exchangeRate: number
  pppFactor: number
  medianIncome: number
  costOfLivingIndex: number
  vatRate: number
  importDutyAvg: number
  region: string
  incomeGroup: 'high' | 'upper-middle' | 'lower-middle' | 'low'
}

export interface ProductPrice {
  localPrice: number
  includesTax: boolean
  taxRate: number
  importDuty: number
  distributionMarkup: number
  reports: number
  notes?: string
}

export interface Product {
  id: string
  name: string
  category: 'digital' | 'physical' | 'saas' | 'essential' | 'service' | 'medical'
  categoryLabel: string
  subcategory: string
  brand: string
  categoryPath: string
  description: string
  unit: string
  prices: Record<string, ProductPrice>
}

export interface FairnessLens {
  id: string
  label: string
  description: string
  calculate: (priceUSD: number, country: Country, product: Product, usPrice: number, globalMedianUSD: number) => number
}

export interface FairnessResult {
  rawScore: number
  pppScore: number
  incomeScore: number
  colScore: number
  priceUSD: number
  usPrice: number
  globalMedianUSD: number
  pppAdjustedPrice: number
  incomePercentage: number
  usIncomePercentage: number
  factors: PriceFactor[]
  hoursOfWork: number
  usHoursOfWork: number
  confidenceScore: number
  confidenceLabel: string
  trendData: TrendPoint[]
  trendSignal: 'buy' | 'wait' | 'neutral'
  trendReason: string
}

export interface TrendPoint {
  month: string
  price: number
  avg: number
}

export interface BrandFairnessEntry {
  brand: string
  avgScore: number
  productCount: number
  worstCountry: string
  bestCountry: string
  category: string
}

export interface PriceFactor {
  label: string
  impact: 'increases' | 'decreases' | 'neutral'
  percentage: number
  description: string
}

export interface QuizQuestion {
  product: Product
  countryA: Country
  countryB: Country
  answer: 'A' | 'B'
  priceA_USD: number
  priceB_USD: number
}

